  var v=Number(pAtm);
  if(!isFinite(v)) return {state:'invalid', value:null, classification:null, source:null, valid:false, reason:'pressure_non_finite'};
  if(v<=0) return {state:'invalid', value:null, classification:null, source:null, valid:false, reason:'pressure_non_positive'};
  if(v<50000) return {state:'invalid', value:null, classification:null, source:null, valid:false, reason:'pressure_below_range'};
  if(v>110000) return {state:'invalid', value:null, classification:null, source:null, valid:false, reason:'pressure_above_range'};
  var cls=(classification==='measured'||classification==='estimated'||classification==='reference')?classification:'entered';
  return {state:'known', value:v, classification:cls, source:'pKpa_field', valid:true, reason:null};
