  var hE=enth(oC,oRH,P), vE=sVol(oC,oRH,P), wBE=wBulb(oC,oRH,P), WE=humR(oC,oRH,P);
  var AF_NOMINAL=2000, afUse=(args.af!==null?args.afm:AF_NOMINAL), afsUse=afUse/3600, mA=afsUse/vE;
