  var dh=hL-hE, Qa=mA*dh;
  return {pressure:prov, suppressed:false, reason:null, hE:hE,vE:vE,wBE:wBE,WE:WE,mA:mA,hLauto:hLauto,lDBauto:lDBauto,lRHauto:lRHauto,lDBuse:lDBuse,lRHuse:lRHuse,hL:hL,vL:vL,wBL:wBL,dh:dh,Qa:Qa};
