  if(!(typeof SH==='number'  && isFinite(SH)  && SH>=PH_SH_MIN_DRY)) return null;       // finite SH >= floor
  if(!(typeof SC==='number'  && isFinite(SC)  && SC>=0)) return null;                   // finite SC >= 0
