  tests.push({name:'Sat. pressure @ 20°C', input:'T=20°C', expected:'2339 Pa', got:fmt(v,0)+' Pa', tol:'±15 Pa', pass:approx(v,2339,15)});

  // 2. Humidity ratio at 25°C, 50% RH, 101325 Pa (ASHRAE: ~0.00988 kg/kg)
  v = humR(25,50,101325);
  tests.push({name:'Humidity ratio @ 25°C/50%', input:'25°C, 50%, 101325Pa', expected:'0.00988 kg/kg', got:fmt(v,5)+' kg/kg', tol:'±0.0002', pass:approx(v,0.00988,0.0002)});

  // 3. Moist air enthalpy at 25°C, 50% RH (ASHRAE: ~50.4 kJ/kg)
  v = enth(25,50,101325);
  tests.push({name:'Enthalpy @ 25°C/50%', input:'25°C, 50%', expected:'50.4 kJ/kg', got:fmt(v,2)+' kJ/kg', tol:'±0.6', pass:approx(v,50.4,0.6)});

  // 4. Dew point at 25°C, 50% RH (≈13.9°C)
  v = dewPt(25,50);
  tests.push({name:'Dew point @ 25°C/50%', input:'25°C, 50%', expected:'13.9°C', got:fmt(v,2)+'°C', tol:'±0.4', pass:approx(v,13.9,0.4)});

  // 5. Wet bulb at 30°C, 40% RH (≈19.9°C)
